shaders.source:
struct Uniforms {
  mvp : mat4x4<f32>,
  normalMatrix : mat3x3<f32>,
  steelDark : vec3<f32>,
  steelLight : vec3<f32>,
  brushGain : f32,
};
@group(0) @binding(0) var<uniform> u : Uniforms;

struct VertexInput {
  @location(0) position : vec3<f32>,
  @location(1) normal : vec3<f32>,
  @location(2) uv : vec2<f32>,
};

struct VertexOutput {
  @builtin(position) position : vec4<f32>,
  @location(0) vNormal : vec3<f32>,
  @location(1) vUv : vec2<f32>,
};

@vertex
fn vertexMain(in : VertexInput) -> VertexOutput {
  var out : VertexOutput;
  out.vNormal = in.normal;
  out.vUv = in.uv;
  out.position = (u.mvp * vec4<f32>(in.position, 1.0));
  return out;
}

@fragment
fn fragmentMain(in : VertexOutput) -> @location(0) vec4<f32> {
  let n = normalize(in.vNormal);
  let brush = (sin((in.vUv.y * 180.0)) * u.brushGain);
  let tangent = (pow(abs(n.x), 2.0) * 0.24);
  let stamped = (smoothstep(0.32, 0.06, length((in.vUv - vec2<f32>(0.5, 0.5)))) * 0.16);
  let body = mix(u.steelDark.rgb, u.steelLight.rgb, ((0.52 + brush) + tangent));
  return vec4<f32>((body * (1.0 - stamped)), 1.0);
}

shaders.vertex:
#version 300 es
in vec3 position;
in vec3 normal;
in vec2 uv;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 steelDark;
uniform vec3 steelLight;
uniform float brushGain;
out vec3 vNormal;
out vec2 vUv;

void main() {
  vNormal = normal;
  vUv = uv;
  gl_Position = (mvp * vec4(position, 1.0));
}

shaders.fragment:
#version 300 es
precision highp float;
uniform mat4 mvp;
uniform mat3 normalMatrix;
uniform vec3 steelDark;
uniform vec3 steelLight;
uniform float brushGain;
in vec3 vNormal;
in vec2 vUv;
out vec4 fragColor;

void main() {
  vec3 n = normalize(vNormal);
  float brush = (sin((vUv.y * 180.0)) * brushGain);
  float tangent = (pow(abs(n.x), 2.0) * 0.24);
  float stamped = (smoothstep(0.32, 0.06, length((vUv - vec2(0.5, 0.5)))) * 0.16);
  vec3 body = mix(steelDark.rgb, steelLight.rgb, ((0.52 + brush) + tangent));
  fragColor = vec4((body * (1.0 - stamped)), 1.0);
}
